#!/usr/bin/env node
/**
 * SyncOut patch v6.3.1 — run from the repo root:   node syncout-patch-v6.3.1.js
 * Works whether you're on v6.2 (what's live) or already applied v6.3.
 *
 * Fix: the booking sheet sat under the tab bar and WhatsApp button, hiding the
 * total and the Book button. Sheets now render above everything; totals and the
 * Continue / Review / Book now buttons stay pinned to the bottom of the sheet;
 * the WhatsApp button hides while a sheet is open and sits above Book buttons.
 *
 * Includes everything in v6.3 (legal pages, careers, QR tickets, accounts, admin).
 */
"use strict";

const fs = require("fs");
const path = require("path");
const crypto = require("crypto");
const { execSync } = require("child_process");

const DRY = process.argv.includes("--dry");
const NO_INSTALL = process.argv.includes("--no-install");
const BACKUP = path.join(".patch-backups", "v6.3.1");

if (!fs.existsSync("src/components/motion/Reveal.tsx")) {
  console.error("\n  Apply v6, v6.1 and v6.2 first (your repo should already have them), then this one.\n");
  process.exit(1);
}

if (!fs.existsSync("package.json")) {
  console.error("\n  Run this from the repo root (no package.json here).\n");
  process.exit(1);
}
try {
  const pkg = JSON.parse(fs.readFileSync("package.json", "utf8"));
  if (pkg.name !== "syncout") {
    console.error("\n  This is the '" + pkg.name + "' repo, not syncout.\n");
    process.exit(1);
  }
} catch {
  console.error("\n  package.json could not be read.\n");
  process.exit(1);
}

